'use client';

import { useState, useEffect } from 'react';

export default function ScreenDetector({ onStreamStart, onStreamStop, isActive }) {
  const [logs, setLogs] = useState([
    { id: 1, text: 'SYS > Neural engine initialized', type: 'normal' },
    { id: 2, text: 'SYS > YOLO-v8 model loaded [OK]', type: 'normal' },
    { id: 3, text: 'SYS > Awaiting screen input...', type: 'warn' },
  ]);
  const [detectionCount, setDetectionCount] = useState(0);
  const [fps, setFps] = useState(0);
  const [uptime, setUptime] = useState(0);

  useEffect(() => {
    let interval;
    if (isActive) {
      interval = setInterval(() => {
        setUptime(prev => prev + 1);
        setFps(Math.floor(Math.random() * 8) + 24);
      }, 1000);
    } else {
      setUptime(0);
      setFps(0);
    }
    return () => clearInterval(interval);
  }, [isActive]);

  const addLog = (text, type = 'normal') => {
    setLogs(prev => [
      ...prev.slice(-6),
      { id: Date.now(), text, type }
    ]);
  };

  const handleStart = async () => {
    try {
      addLog('SYS > Requesting display capture...', 'warn');
      const stream = await navigator.mediaDevices.getDisplayMedia({
        video: { frameRate: 30 },
        audio: false,
      });
      addLog('SYS > Display capture granted [OK]', 'normal');
      addLog('SYS > Initializing AI detection pipeline...', 'normal');
      setTimeout(() => addLog('SYS > Vehicle tracker [ACTIVE]', 'normal'), 600);
      setTimeout(() => addLog('SYS > Plate reader [ACTIVE]', 'normal'), 1000);
      onStreamStart(stream);
    } catch (err) {
      addLog(`ERR > Capture denied: ${err.message}`, 'alert');
    }
  };

  const handleStop = () => {
    addLog('SYS > Detection stream terminated', 'warn');
    addLog('SYS > Saving session data...', 'normal');
    onStreamStop();
  };

  const formatUptime = (secs) => {
    const m = Math.floor(secs / 60).toString().padStart(2, '0');
    const s = (secs % 60).toString().padStart(2, '0');
    return `${m}:${s}`;
  };

  return (
    <div className="panel" style={{ height: '100%' }}>
      <div className="panel-header">
        <span className="panel-title">Screen Detection</span>
        <span
          className="panel-badge"
          style={{
            background: isActive ? 'rgba(34,197,94,0.1)' : 'rgba(100,116,139,0.1)',
            color: isActive ? '#22c55e' : '#64748b',
            border: `1px solid ${isActive ? 'rgba(34,197,94,0.3)' : 'rgba(100,116,139,0.2)'}`,
          }}
        >
          {isActive ? '● LIVE' : '○ IDLE'}
        </span>
      </div>

      <div className="panel-body">
        {/* AI Status Widget */}
        <div className="ai-status-widget">
          <div className="ai-status-header">
            <span className="ai-status-title">AI Engine</span>
            <span
              className="ai-status-value"
              style={{ color: isActive ? '#22c55e' : '#ef4444' }}
            >
              {isActive ? 'ONLINE' : 'STANDBY'}
            </span>
          </div>
          {isActive && (
            <div className="ai-status-bar">
              <div className="ai-status-bar-fill" />
            </div>
          )}
        </div>

        {/* Info Rows */}
        <div className="detector-status">
          <div className="detector-info-row">
            <span className="detector-info-label">Status</span>
            <span className="detector-info-value" style={{ color: isActive ? '#22c55e' : '#64748b' }}>
              {isActive ? '▶ DETECTING' : '■ STOPPED'}
            </span>
          </div>
          <div className="detector-info-row">
            <span className="detector-info-label">FPS</span>
            <span className="detector-info-value">{isActive ? fps : '--'}</span>
          </div>
          <div className="detector-info-row">
            <span className="detector-info-label">Uptime</span>
            <span className="detector-info-value">{isActive ? formatUptime(uptime) : '00:00'}</span>
          </div>
          <div className="detector-info-row">
            <span className="detector-info-label">Model</span>
            <span className="detector-info-value" style={{ color: '#06b6d4', fontSize: '9px' }}>YOLO-v8-NANO</span>
          </div>
        </div>

        {/* Buttons */}
        <button
          className="btn btn-start"
          onClick={handleStart}
          disabled={isActive}
        >
          <span>▶</span>
          START SCREEN DETECTION
        </button>
        <button
          className="btn btn-stop"
          onClick={handleStop}
          disabled={!isActive}
        >
          <span>■</span>
          STOP DETECTION
        </button>

        {/* Log Terminal */}
        <div style={{ marginTop: '14px' }}>
          <div style={{
            fontFamily: 'var(--font-mono)',
            fontSize: '9px',
            color: 'var(--text-muted)',
            letterSpacing: '2px',
            marginBottom: '8px',
            textTransform: 'uppercase'
          }}>
            System Log
          </div>
          <div className="detection-log">
            {logs.map(log => (
              <div key={log.id} className={`log-entry ${log.type}`}>
                {log.text}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
